package main

import (
	"bytes"
	"flag"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/taybart/midnight/luagen"
	"github.com/taybart/midnight/parse"
)

// compiledFooter marks Lua files generated by `midnight compile`. Same as the
// reference compiler, so either CLI recognizes the other's output.
const compiledFooter = "-- __MIDNIGHT_COMPILED__"

const compileUsage = `Usage: midnight compile [options] [paths]
Compiles Midnight files (or all *.mn and *.midnight files under directories) into Lua, writing
foo.mn to foo.lua. Paths default to the current directory, or to compile.src of
the nearest midnight.json:

  { "compile": { "src": "midnight", "out": "lua" } }

which also compiles files under src to the same path under out.
Available options are:
  -o dir   output directory: files under a directory path keep their path
           relative to it (src/a/b.mn -> dir/a/b.lua), named files go
           directly in it (src/a/b.mn -> dir/b.lua)
  -w       watch: recompile files as they change (and remove the Lua compiled
           from deleted ones) until interrupted
  -project only compile files under compile.src of a midnight.json (others
           are skipped), ex. for editors compiling a file on save
  -f       overwrite existing Lua files (by default only files generated by
           'midnight compile' are overwritten)
  -p       print compiled code instead of writing files
  -markup-factory name
           function markup elements call (default: h, see docs/MARKUP.md)`

// compileCommand implements `midnight compile`, mirroring the reference compiler's
// CLI (https://erde-lang.github.io/docs/cli).
func compileCommand(args []string) int {
	var opt_o string
	var midnightOpts parse.MidnightOptions
	var opt_f, opt_p, opt_w, opt_project bool
	flags := flag.NewFlagSet("compile", flag.ContinueOnError)
	flags.StringVar(&opt_o, "o", "", "")
	flags.Var(markupFactoryFlag{&midnightOpts}, "markup-factory", "")
	flags.BoolVar(&opt_f, "f", false, "")
	flags.BoolVar(&opt_p, "p", false, "")
	flags.BoolVar(&opt_w, "w", false, "")
	flags.BoolVar(&opt_project, "project", false, "")
	flags.SetOutput(io.Discard)
	flags.Usage = func() {}

	paths, err := parseInterspersed(flags, args)
	if err == flag.ErrHelp {
		fmt.Println(compileUsage)
		return 0
	} else if err != nil {
		fmt.Println(err.Error())
		return 1
	}

	project, err := findProject(".")
	if err != nil {
		fmt.Println(err.Error())
		return 1
	}
	if len(paths) == 0 {
		if project != nil {
			paths = []string{displayPath(project.src)}
		} else {
			paths = []string{"."}
		}
	}

	c := &compiler{outdir: opt_o, force: opt_f, print: opt_p, opts: midnightOpts, project: project, onlyProject: opt_project}
	if opt_w {
		if opt_p {
			fmt.Println("cannot use -w w/ -p")
			return 1
		}
		return c.watch(paths)
	}

	for _, root := range paths {
		files, err := compileTargets(root)
		if err != nil {
			fmt.Println(err.Error())
			return 1
		}
		for _, file := range files {
			if !c.compileFile(file, root) {
				return 1
			}
		}
	}

	return 0
}

var errCompileFailed = fmt.Errorf("compile failed")

type compiler struct {
	outdir  string
	force   bool
	print   bool
	opts    parse.MidnightOptions
	project *projectConfig // found from the working directory

	projects map[string]*projectConfig // by directory, see projectFor

	onlyProject bool // -project: skip files outside compile.src
}

// compileTargets returns the files to compile for a path: the path itself
// for a file (whatever its extension), or the midnight files under a directory.
func compileTargets(root string) ([]string, error) {
	info, err := os.Stat(root)
	if err != nil {
		return nil, err
	}
	if !info.IsDir() {
		return []string{root}, nil
	}
	var files []string
	err = filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if !d.IsDir() && parse.IsMidnightPath(path) {
			files = append(files, path)
		}
		return nil
	})
	return files, err
}

// outputPath returns where path (found under root, a directory or path
// itself) compiles to:
//   - w/ -o: under it, keeping the path relative to a directory root (or just
//     the file name, for a file named directly)
//   - under the project's compile.src: the same path under compile.out
//   - otherwise next to the source
func (c *compiler) outputPath(path, root string) string {
	lua := parse.TrimMidnightExt(path) + ".lua"
	if c.outdir != "" {
		if root == path {
			return filepath.Join(c.outdir, filepath.Base(lua))
		}
		if rel, err := filepath.Rel(root, lua); err == nil {
			return filepath.Join(c.outdir, rel)
		}
		return filepath.Join(c.outdir, lua)
	}
	if out, ok := c.projectFor(path).outputFor(lua); ok {
		return displayPath(out)
	}
	return lua
}

// projectFor returns the midnight.json for path: the nearest one to the file
// (so editors can compile a file from any working directory), or the one
// found from the working directory.
func (c *compiler) projectFor(path string) *projectConfig {
	dir := filepath.Dir(path)
	if cfg, ok := c.projects[dir]; ok {
		return cfg
	}
	cfg, err := findProject(dir)
	if err != nil || cfg == nil {
		cfg = c.project
	}
	if c.projects == nil {
		c.projects = map[string]*projectConfig{}
	}
	c.projects[dir] = cfg
	return cfg
}

// watch compiles paths, then polls them for changes until interrupted.
// Changed files are recompiled (failures are reported, not fatal), and the
// compiled Lua of deleted files is removed.
func (c *compiler) watch(paths []string) int {
	type source struct {
		root    string
		modTime time.Time
	}
	known := map[string]source{}

	scan := func() {
		seen := map[string]bool{}
		for _, root := range paths {
			files, err := compileTargets(root)
			if err != nil {
				continue // ex. a file being replaced by an editor
			}
			for _, file := range files {
				seen[file] = true
				info, err := os.Stat(file)
				if err != nil {
					continue
				}
				if prev, ok := known[file]; ok && prev.modTime.Equal(info.ModTime()) {
					continue
				}
				known[file] = source{root: root, modTime: info.ModTime()}
				c.compileFile(file, root)
			}
		}
		for file, src := range known {
			if seen[file] {
				continue
			}
			delete(known, file)
			out := c.outputPath(file, src.root)
			if isCompiledFile(out) && os.Remove(out) == nil {
				fmt.Printf("%s => DELETED %s\n", file, out)
			}
		}
	}

	scan()
	fmt.Println("watching for changes (ctrl-c to stop)")
	for range time.Tick(300 * time.Millisecond) {
		scan()
	}
	return 0
}

const cleanUsage = `Usage: midnight clean [paths]
Removes Lua files generated by 'midnight compile' (files ending w/ the '` + compiledFooter + `'
footer), or all such files under directories. Paths default to the current
directory. Other Lua files are never removed.`

// cleanCommand implements `midnight clean`, mirroring the reference compiler's CLI.
func cleanCommand(args []string) int {
	flags := flag.NewFlagSet("clean", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	flags.Usage = func() {}

	paths, err := parseInterspersed(flags, args)
	if err == flag.ErrHelp {
		fmt.Println(cleanUsage)
		return 0
	} else if err != nil {
		fmt.Println(err.Error())
		return 1
	}

	if len(paths) == 0 {
		paths = []string{"."}
	}

	status := 0
	for _, root := range paths {
		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() || !strings.HasSuffix(path, ".lua") || !isCompiledFile(path) {
				return nil
			}
			if err := os.Remove(path); err != nil {
				fmt.Printf("%s => ERROR\n%s\n", path, err)
				status = 1
				return nil
			}
			fmt.Printf("%s => DELETED\n", path)
			return nil
		})
		if err != nil {
			fmt.Println(err.Error())
			status = 1
		}
	}

	return status
}

// compileFile compiles path (found under root, see outputPath).
func (c *compiler) compileFile(path, root string) bool {
	if c.onlyProject {
		if _, ok := c.projectFor(path).outputFor(path); !ok {
			return true
		}
	}
	compilePath := c.outputPath(path, root)
	force, print, midnightOpts := c.force, c.print, c.opts

	if !print && !force && fileExists(compilePath) && !isCompiledFile(compilePath) {
		fmt.Printf("%s => ERROR\n", path)
		fmt.Printf("Cannot write to %s: file already exists (use -f to overwrite)\n", compilePath)
		return false
	}

	source, err := os.ReadFile(path)
	if err != nil {
		fmt.Printf("%s => ERROR\n%s\n", path, err)
		return false
	}

	chunk, err := parse.ParseMidnightWithOptions(bytes.NewReader(source), path, midnightOpts)
	if err != nil {
		fmt.Printf("%s => ERROR\n%s\n", path, err)
		return false
	}

	compiled := luagen.Generate(chunk)
	if !strings.HasSuffix(compiled, "\n") {
		compiled += "\n"
	}
	compiled += compiledFooter

	if print {
		fmt.Println(path)
		fmt.Println(strings.Repeat("-", len(path)))
		fmt.Println(compiled)
		return true
	}

	if err := os.MkdirAll(filepath.Dir(compilePath), 0o755); err != nil {
		fmt.Printf("%s => ERROR\n%s\n", path, err)
		return false
	}
	if err := os.WriteFile(compilePath, []byte(compiled), 0o644); err != nil {
		fmt.Printf("%s => ERROR\n%s\n", path, err)
		return false
	}

	fmt.Printf("%s => %s\n", path, compilePath)
	return true
}

func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

// isCompiledFile checks whether a Lua file was generated by `midnight compile`
// (ends w/ compiledFooter, allowing for a trailing newline added by editors).
func isCompiledFile(path string) bool {
	source, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	return strings.HasSuffix(strings.TrimRight(string(source), "\r\n"), compiledFooter)
}

// parseInterspersed parses flags that may come after positional args (ex.
// `midnight compile src -o dest`), which the flag package doesn't support.
func parseInterspersed(flags *flag.FlagSet, args []string) ([]string, error) {
	var positional []string
	for {
		if err := flags.Parse(args); err != nil {
			return nil, err
		}
		args = flags.Args()
		if len(args) == 0 {
			return positional, nil
		}
		positional = append(positional, args[0])
		args = args[1:]
	}
}
